create index if not exists jobs_queue_idx on automation_jobs(status,priority,created_at);create index if not exists jobs_lease_idx on automation_jobs(lease_until);create index if not exists jobs_channel_idx on automation_jobs(channel_id,created_at);create index if not exists faults_status_idx on faults(status,created_at);create index if not exists heartbeat_idx on workers(last_heartbeat);create index if not exists analytics_channel_idx on analytics(channel_id,observed_at desc);
create or replace function claim_next_job(p_worker_id text) returns setof automation_jobs language plpgsql security definer as $$declare j automation_jobs;begin update automation_jobs set status='running',worker_id=p_worker_id,lease_until=now()+interval '90 seconds',updated_at=now() where id=(select id from automation_jobs where status='queued' and (next_attempt_at is null or next_attempt_at<=now()) order by priority asc,created_at asc for update skip locked limit 1) returning * into j; if j.id is not null then return next j; end if;end$$;
create or replace function watchdog_workers() returns void language sql security definer as $$update workers set status='offline',updated_at=now() where last_heartbeat < now()-interval '90 seconds';$$;
create or replace function recover_stale_workers() returns void language sql security definer as $$update automation_jobs set status='queued',worker_id=null,lease_until=null,updated_at=now() where status='running' and lease_until < now();$$;
create or replace function reconcile_queue() returns void language sql security definer as $$update automation_jobs set status='queued',updated_at=now() where status='retrying' and next_attempt_at<=now();$$;
create or replace function reconcile_schedules() returns void language sql security definer as $$update schedules set next_run_at=publish_at where enabled and next_run_at is null;$$;
create or replace function reconcile_system() returns void language sql security definer as $$select recover_stale_workers();select reconcile_queue();select watchdog_workers();$$;
create or replace function cleanup_expired_artifacts() returns void language sql security definer as $$delete from artifact_versions where created_at<now()-interval '7 days';$$;
